public class TwosComplementTool {

    public static String toBinary8(int value) {
        if (value < -128 || value > 127) {
            return null;
        }
        int pattern = value;
        if (pattern < 0) {
            pattern = pattern + 256;
        }
        StringBuilder sb = new StringBuilder();
        for (int bit = 7; bit >= 0; bit--) {
            int mask = 1 << bit;
            sb.append((pattern & mask) != 0 ? '1' : '0');
        }
        return sb.toString();
    }

    public static Integer fromBinary8(String bits) {
        if (bits == null || bits.length() != 8) {
            return null;
        }
        int value = 0;
        for (int i = 0; i < 8; i++) {
            char c = bits.charAt(i);
            if (c != '0' && c != '1') {
                return null;
            }
            value = value * 2 + (c - '0');
        }
        if (value >= 128) {
            value = value - 256;
        }
        return value;
    }
}
